let state,storageError='',active='all',route='dashboard',query='',editing=null,formAttachments=[],pendingFiles=[],staff=[],busy=false,importSheets=[],analysis=null;
try{let raw=localStorage.getItem(key);state=raw?JSON.parse(raw):M.blank();M.validate(state)}catch(e){state=M.blank();storageError='Não foi possível carregar os dados salvos: '+e.message;}
function notify(msg){$('toast').textContent=msg;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',7000)}
function persist(next){if(storageError)throw Error(storageError+' Exporte os dados e restaure um backup válido antes de salvar.');M.validate(next);try{localStorage.setItem(key,JSON.stringify(next))}catch(e){throw Error('Não foi possível salvar. Exporte um backup e confira o espaço disponível.')}state=next;}
const records=k=>state[k].filter(r=>k==='projects'||active==='all'||r.project===active);
const get=(k,id)=>state[k].find(r=>r.id===id);
